// LINE postback data e.g. mode=confirm&answer=yes&chatLogId=12
const out = [];
for (const item of $input.all()) {
  const raw = String(item.json.text || '');
  const params = {};
  for (const pair of raw.split('&')) {
    const kv = pair.split('=');
    if (kv[0]) params[decodeURIComponent(kv[0])] = decodeURIComponent(kv.slice(1).join('=') || '');
  }
  out.push({ json: {
    ...item.json,
    mode: params.mode || '',
    answer: params.answer || '',
    chatLogId: params.chatLogId || ''
  }});
}
return out;

const src = $('Switch - Mode').item.json;
let parsed = { intent: 'Other', confidence: 0, suggested_steps: [] };
try {
  const raw = $input.first().json.candidates[0].content.parts[0].text;
  const cleaned = raw.replace(/```json|```/g, '').trim();
  const j = JSON.parse(cleaned);
  parsed = {
    intent: j.intent || 'Other',
    confidence: Number(j.confidence) || 0,
    suggested_steps: Array.isArray(j.suggested_steps) ? j.suggested_steps : []
  };
} catch (e) {
  parsed.intent = 'Other';
}
return [{ json: { ...parsed, userId: src.userId, problemDetail: src.problemDetail, replyToken: src.replyToken } }];

const sum = $('Postgres - Aggregate Ticket Summary').first().json;
const pick = (name, key) => $(name).all().map(i => `${i.json[key] ?? '-'}:${i.json.cnt}`).join(', ');
return [{ json: {
  report_date: new Date().toISOString().slice(0,10),
  total_tickets: Number(sum.total_tickets || 0),
  today_tickets: Number(sum.today_tickets || 0),
  month_tickets: Number(sum.month_tickets || 0),
  in_progress: Number(sum.in_progress || 0),
  closed_tickets: Number(sum.closed_tickets || 0),
  avg_repair_hours: sum.avg_repair_hours ? Number(Number(sum.avg_repair_hours).toFixed(2)) : 0,
  resolved_by_chatbot: Number(sum.resolved_by_chatbot || 0),
  escalated_to_staff: Number(sum.escalated_to_staff || 0),
  top_problem_types: pick('Postgres - Top Problem Types','intent'),
  top_problem_devices: pick('Postgres - Top Problem Devices','device_id'),
  top_organizations: pick('Postgres - Top Schools/Orgs','organization')
}}];

// Gather ticket data from whichever feeder Set node ran (only one per execution)
const candidates = ['Set - Ticket Input (Postback)','Set - Map Web Form Fields','Set - Ticket Input (Low Confidence)','Set - Ticket Input (Not Resolved)'];
let ctx = {};
for (const n of candidates) {
  try { const it = $(n).item; if (it && it.json && Object.keys(it.json).length) { ctx = it.json; break; } } catch(e) {}
}
return [{ json: ctx }];
